const normSchool=n=>String(n||"").toLowerCase().replace(/[^a-z0-9]/g,"");
const SCHOOL_EXCLUDE=new Set(["fudma","federaluniversityotueke"]);
const schoolAliasMap=new Map(),schoolMap=new Map();
for(const x of [...SCHOOLS,...EXTRA_SCHOOLS]){const k=normSchool(x[0]);if(SCHOOL_EXCLUDE.has(k))continue;if(!schoolAliasMap.has(k))schoolAliasMap.set(k,[]);const al=schoolAliasMap.get(k);if(!al.includes(x[0]))al.push(x[0]);const prev=schoolMap.get(k);if(!prev)schoolMap.set(k,{fullName:x[0],abbr:x[1],type:x[2],state:x[3]});else if(String(x[1]).length>String(prev.abbr).length)prev.abbr=x[1]}
const schools=[...schoolMap.values()];
function canonicalSchool(n){return schoolMap.get(normSchool(n))?.fullName||""}
function schoolAliases(n){return schoolAliasMap.get(normSchool(n))||[String(n||"")]}
state.school=canonicalSchool(state.school)||state.school;
let toastTimer=0;function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2600)}
function save(){try{localStorage.setItem("cbc_school",state.school);localStorage.setItem("cbc_favs",JSON.stringify(state.favorites));localStorage.setItem("cbc_welcome_seen",state.welcomeSeen?"1":"0")}catch{toast("Local storage is unavailable on this browser.")}}
function saveOwnerDraft(){if(!state.user)return;try{localStorage.setItem(ownerDraftKey(state.user.uid),JSON.stringify(ownerListing))}catch{toast("Draft storage is unavailable on this browser.")}}
function loadOwnerDraft(user){try{ownerListing=JSON.parse(localStorage.getItem(ownerDraftKey(user.uid))||"{}")||{}}catch{ownerListing={}}}
function driveConnected(user){return !!user&&localStorage.getItem(driveStateKey(user.uid))==="1"}
function saveDriveConnection(user,connected){if(!user)return;try{localStorage.setItem(driveStateKey(user.uid),connected?"1":"0")}catch{}}
function safeWebsite(value){try{const u=new URL(String(value||""));return ["http:","https:"].includes(u.protocol)?u.href:""}catch{return""}}
function normalizePublishedListing(b){return {...b,id:b.id,ownerUid:b.ownerUid||b.uid||String(b.id||"").replace(/^owner_/,""),school:b.school||"",name:b.businessName||b.name||"",cat:b.category||b.cat||"",price:Number(b.priceFrom||b.price||0),loc:b.address||b.location||"",delivery:b.delivery||"By arrangement",about:b.shortDescription||b.about||"",wa:b.whatsapp||b.wa||"",email:b.email||"",imageUrl:b.featuredImageUrl||b.imageUrl||"",website:safeWebsite(b.website),description:b.description||"",hours:b.hours||"",priceRange:b.priceRange||"",productImages:Array.isArray(b.productImages)?b.productImages:[],ratingAvg:Number(b.ratingAvg||0),ratingCount:Number(b.ratingCount||0),trustedStore:b.trustedStore===true};}
function selectedBusinesses(){if(!state.school)return [];return publishedListings.map(normalizePublishedListing).filter(b=>normSchool(b.school)===normSchool(state.school))}
function getBusiness(id){return selectedBusinesses().find(x=>x.id===id)||null}
let listingsInflight=null,listingsInflightSchool="";
function loadPublishedListings(){const school=state.school;if(publishedListingsLoaded||!school)return Promise.resolve();if(listingsInflight&&listingsInflightSchool===school)return listingsInflight;listingsInflightSchool=school;const job=(async()=>{try{const alias=schoolAliases(school).join("|");const r=await fetch(`/api/storage/upload?action=list&school=${encodeURIComponent(school)}&alias=${encodeURIComponent(alias)}`);const d=await r.json().catch(()=>({}));if(r.ok&&d.ok&&school===state.school){publishedListings=Array.isArray(d.listings)?d.listings:[];publishedListingsLoaded=true;renderAll()}}catch(e){console.warn("Published listings could not be loaded",e)}finally{if(listingsInflight===job)listingsInflight=null}})();listingsInflight=job;return job}
function productCarousel(b){const imgs=Array.isArray(b.productImages)?b.productImages.filter(Boolean):[];if(!imgs.length)return "";return `<div class="detail-section product-gallery"><div class="gallery-head"><div><span class="eyebrow">Gallery</span><h2>Products & services</h2></div><span class="muted">Swipe to explore · ${imgs.length}</span></div><div class="product-carousel">${imgs.map((src,i)=>`<div class="product-slide"><img src="${esc(src)}" alt="${esc(b.name)} product ${i+1}" loading="lazy" decoding="async"></div>`).join("")}</div></div>`}
function closeDrawer(){const d=$("#drawer"),b=$("#backdrop");d?.classList.remove("open");d?.setAttribute("aria-hidden","true");b?.classList.add("hidden")}
function businessImage(b,large=false){const src=b.imageUrl||b.image||"assets/icon-512.png";return `<img src="${esc(src)}" alt="${esc(b.name)}" loading="lazy" decoding="async"${large?' class="detail-image"':''}>`}
function waUrl(b){let n=String(b.wa||"").replace(/[^0-9]/g,"");if(n.startsWith("0"))n="234"+n.slice(1);else if(n.length===10)n="234"+n;return n?`https://wa.me/${n}?text=${encodeURIComponent(`Hello ${b.name}, I found your business on CampBiz.`)}`:"#"}
function card(b){return `<article class="biz-card" data-business="${esc(b.id)}" tabindex="0" role="button"><div class="biz-image">${businessImage(b)}</div><div class="biz-card-body"><span class="eyebrow">${esc(b.cat)}</span><h3>${esc(b.name)} ${b.trustedStore?`<span class="trusted-badge">✓ Trusted store</span>`:""}</h3><p>${esc(b.about)}</p><div class="biz-meta"><span>Store ${b.ratingCount?`⭐ ${b.ratingAvg.toFixed(1)} · ${b.ratingCount} ratings`:`rating pending`}</span><span>₦${Number(b.price||0).toLocaleString()}+</span></div></div></article>`}
function wireBusinessActions(root=document){root.querySelectorAll("[data-business]").forEach(el=>{const open=()=>openBusiness(el.dataset.business);el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});root.querySelectorAll("[data-store]").forEach(el=>el.onclick=()=>openStore(el.dataset.store));root.querySelectorAll("[data-fav]").forEach(el=>el.onclick=()=>{const id=el.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();toast(state.favorites.includes(id)?"Saved to your businesses.":"Removed from saved businesses.");openBusiness(id)})}
function renderHome(){const list=selectedBusinesses(),trusted=list.filter(b=>b.trustedStore);const fyp=$("#fyp"),name=$("#campusName");if(name)name.textContent=state.school||"Choose your school";if(fyp)fyp.innerHTML=list.length?`<div class="grid">${list.map(card).join("")}</div>`:`<div class="empty-state"><h2>No published businesses yet</h2><p>There are no CampBiz listings published for <strong>${esc(state.school)}</strong> yet.</p><button class="primary" id="changeSchoolHome">Change school</button></div>`;$("#changeSchoolHome")?.addEventListener("click",()=>goSchoolPicker(location.hash||"#home"));const tc=$("#trustedStores");if(tc){const rotatingTrusted=[...trusted];const key=`cbc_trusted_order_${encodeURIComponent(state.school||"default")}`;let previous=[];try{previous=JSON.parse(localStorage.getItem(key)||"[]")}catch{}if(rotatingTrusted.length>1){for(let attempt=0;attempt<5;attempt++){for(let i=rotatingTrusted.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[rotatingTrusted[i],rotatingTrusted[j]]=[rotatingTrusted[j],rotatingTrusted[i]];}const current=rotatingTrusted.map(x=>x.ownerUid||x.id);if(current.join("|")!==previous.join("|"))break;}try{localStorage.setItem(key,JSON.stringify(rotatingTrusted.map(x=>x.ownerUid||x.id)))}catch{}}tc.innerHTML=rotatingTrusted.length?rotatingTrusted.map(storeCard).join(""):'<p class="muted">Trusted stores appear here after reaching 4.5+ from 100+ client ratings.</p>';}renderTools();wireBusinessActions()}
function renderResults(){const q=($("#searchInput")?.value||"").trim().toLowerCase();const cat=$("#categoryFilter")?.value||"";const price=$("#priceFilter")?.value||"";let list=selectedBusinesses().filter(b=>{const text=[b.name,b.cat,b.about,b.description,b.loc].join(" ").toLowerCase();if(q&&!text.includes(q))return false;if(cat&&b.cat!==cat)return false;const n=Number(b.price||0);if(price==='low'&&n>=3000)return false;if(price==='mid'&&(n<3000||n>10000))return false;if(price==='high'&&n<=10000)return false;return true});const out=$("#results");if(out)out.innerHTML=list.length?list.map(card).join(""):`<div class="empty-state"><h2>No matches</h2><p>Try another search or category.</p></div>`;wireBusinessActions(out||document)}
function renderFavorites(){const out=$("#favoritesGrid");const list=selectedBusinesses().filter(b=>state.favorites.includes(b.id));if(out)out.innerHTML=list.length?list.map(card).join(""):`<div class="empty-state"><h2>No saved businesses</h2><p>Save businesses from their view page to find them here.</p></div>`;wireBusinessActions(out||document)}
function populateCategories(){const s=$("#categoryFilter");if(s)s.innerHTML='<option value="">All categories</option>'+CATEGORIES.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join("");const m=$("#categoryMenu");if(m)m.innerHTML=CATEGORIES.map(c=>`<button type="button" class="menu-link category-link" data-category="${esc(c)}">${esc(c)}</button>`).join("");m?.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{location.hash='search';setTimeout(()=>{const s=$("#categoryFilter");if(s)s.value=b.dataset.category;renderResults();closeDrawer()},0)})}
function renderAll(){renderHome();renderResults();renderFavorites();if(location.hash==='#owner'&&!document.activeElement?.closest?.('#listingWorkspace'))renderOwnerDashboard()}
let schoolBeforePicker="";
function goSchoolPicker(targetRoute=""){schoolBeforePicker=state.school;if(targetRoute)pendingRoute=targetRoute;else if(location.hash&&location.hash!=="#")pendingRoute=location.hash;const w=$("#welcomeScreen"),p=$("#schoolPicker"),a=$("#appLayout"),t=$("#topbar");w?.classList.add("hidden");a?.classList.add("hidden");t?.classList.add("hidden");p?.classList.remove("hidden");populateSchoolPicker()}
function showFirstVisit(){$("#schoolPicker")?.classList.add("hidden");$("#welcomeScreen")?.classList.add("hidden");$("#topbar")?.classList.remove("hidden");$("#appLayout")?.classList.remove("hidden")}
function showToolsWithoutSchool(){showFirstVisit()}
function populateSchoolPicker(){
 const input=$("#schoolSelect"),drop=$("#schoolDropdown"),cont=$("#continueSchool");if(!input||!drop||!cont)return;
 let type="All";const types=["All",...Array.from(new Set(schools.map(s=>s.type))).sort()];const host=input.parentElement;
 let chips=host.querySelector(".school-type-chips");if(!chips){chips=document.createElement("div");chips.className="school-type-chips";chips.innerHTML=types.map(t=>`<button type="button" class="school-type-chip ${t==="All"?"active":""}" data-school-type="${esc(t)}">${esc(t)}</button>`).join("");host.appendChild(chips)}
 const render=()=>{const q=input.value.trim().toLowerCase();const matches=schools.filter(s=>(type==="All"||s.type===type)&&(!q||s.fullName.toLowerCase().includes(q)||s.abbr.toLowerCase().includes(q)||s.state.toLowerCase().includes(q))).slice(0,80);drop.innerHTML=matches.map(s=>`<button type="button" class="school-option" data-school="${esc(s.fullName)}"><strong>${esc(s.fullName)}</strong><small>${esc(s.abbr)} · ${esc(s.type)} · ${esc(s.state)}</small></button>`).join("")||'<p class="school-empty">No school found. Try a different name, abbreviation or state.</p>';drop.classList.remove("hidden");input.setAttribute("aria-expanded","true");drop.querySelectorAll("[data-school]").forEach(b=>b.onclick=()=>{input.value=b.dataset.school;state.school=b.dataset.school;cont.disabled=false;drop.classList.add("hidden");input.setAttribute("aria-expanded","false")})};
 chips.querySelectorAll(".school-type-chip").forEach(x=>x.classList.toggle("active",x.dataset.schoolType==="All"));if(!host.dataset.outside){host.dataset.outside="1";document.addEventListener("click",e=>{if(!host.contains(e.target))drop.classList.add("hidden")})}chips.querySelectorAll("[data-school-type]").forEach(b=>b.onclick=()=>{type=b.dataset.schoolType;chips.querySelectorAll(".school-type-chip").forEach(x=>x.classList.toggle("active",x===b));render();input.focus()});input.onfocus=render;input.onclick=render;input.oninput=()=>{state.school="";cont.disabled=true;render()};cont.onclick=()=>{if(!state.school){toast("Choose your school first.");input.focus();return}state.welcomeSeen=true;save();$("#schoolPicker")?.classList.add("hidden");$("#welcomeScreen")?.classList.add("hidden");$("#topbar")?.classList.remove("hidden");$("#appLayout")?.classList.remove("hidden");publishedListingsLoaded=false;publishedListings=[];loadPublishedListings();renderAll();const target=pendingRoute||"#home";pendingRoute="";location.hash=target.replace(/^#/ ,"")||"home";route()};if(state.school){input.value=state.school;cont.disabled=false}
}

function safeDecode(v){try{return decodeURIComponent(v)}catch{return v}}
let renderedBusiness="",renderedStore="";
function route(){const raw=location.hash.replace('#','')||'';let [hash,param]=raw.split('/');const known=['home','search','favorites','businessView','store','owner','tools','about'];const schoolRequired=['home','search','favorites','businessView','store','owner'];if(hash&&!known.includes(hash))hash=state.school?'home':'';if(!hash&&state.school)hash='home';if(!state.school&&schoolRequired.includes(hash)){goSchoolPicker(location.hash);return}if((hash==='businessView'||hash==='store')&&!param){location.hash='home';return}if(hash==='tools'||hash==='about'){showToolsWithoutSchool()}else if(schoolRequired.includes(hash)){showFirstVisit()}else{$("#appLayout")?.classList.add("hidden");$("#topbar")?.classList.add("hidden");$("#welcomeScreen")?.classList.remove("hidden")}document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===hash));if(hash==='home')renderHome();if(hash==='search')renderResults();if(hash==='favorites')renderFavorites();if(hash==='owner')renderOwnerDashboard();if(hash==='businessView'){const id=safeDecode(param);if(id!==renderedBusiness)openBusiness(id);else wireBusinessActions()}if(hash==='store'){const id=safeDecode(param);if(id!==renderedStore)openStore(id)}closeDrawer()}
function updateAccountUI(){
 const a=$("#drawerAccount");if(a)a.classList.toggle('hidden',!state.user);
 const owner=$("#ownerLogin"), ownerDash=$("#ownerGoDashboard");
 if(owner)owner.classList.toggle("hidden",!!state.user);
 if(ownerDash)ownerDash.classList.toggle("hidden",!state.user);
}
async function verifySubscriptionReturn(user){const params=new URLSearchParams(location.search);const reference=params.get('reference');const flow=params.get('subscription');if(!user||!reference||!['trial-enroll','return'].includes(flow))return;try{const token=await user.getIdToken();const endpoint=flow==='trial-enroll'?'/api/subscription/trial-verify':'/api/subscription/verify';const r=await fetch(endpoint,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({reference})});const d=await r.json().catch(()=>({}));toast(d.message||d.error||'Billing setup completed.');history.replaceState({},'',location.pathname);location.hash='owner';$('#modal')?.classList.remove('show');upgradePrompted=false;await updateOwnerAccess(user);refreshFeedAfterBilling()}catch(e){toast('Could not verify the billing setup yet. Please try again.')}}
async function enrollTrialBilling(){const plan=document.querySelector('input[name="ownerPlan"]:checked')?.value||'monthly';const user=auth.currentUser;if(!user){toast('Sign in with Google first.');return}try{const token=await user.getIdToken();const r=await fetch('/api/subscription/trial-enroll',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({plan})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Unable to set up billing.');if(d.authorizationUrl)location.href=d.authorizationUrl;else toast(d.message||'Billing setup completed.')}catch(e){toast(e.message||'Unable to set up billing.')}}
async function activateTrialBilling(){const user=auth.currentUser;if(!user)return;try{const token=await user.getIdToken();const r=await fetch('/api/subscription/activate-trial',{method:'POST',headers:{Authorization:`Bearer ${token}`}});const d=await r.json().catch(()=>({}));toast(d.message||d.error||'Billing update complete.');await updateOwnerAccess(user);refreshFeedAfterBilling()}catch(e){toast('Unable to start billing automatically.')}}
async function startSubscription(planArg){const plan=(typeof planArg==='string'&&planArg)?planArg:(document.querySelector('input[name="ownerPlan"]:checked')?.value||'monthly');const user=auth.currentUser;if(!user){toast('Sign in with Google first.');return}try{const token=await user.getIdToken();const r=await fetch('/api/subscription/checkout',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({plan})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Unable to start Paystack checkout.');if(d.authorizationUrl)location.href=d.authorizationUrl;else toast(d.message||'Paystack checkout ready.')}catch(e){toast(e.message||'Unable to start subscription.')}}
function setup(){populateCategories();$("#searchBtn")?.addEventListener('click',renderResults);$("#searchInput")?.addEventListener('keydown',e=>{if(e.key==='Enter')renderResults()});$("#categoryFilter")?.addEventListener('change',renderResults);$("#priceFilter")?.addEventListener('change',renderResults);$("#fypSearch")?.addEventListener('keydown',e=>{if(e.key==='Enter'){const si=$("#searchInput");if(si)si.value=e.target.value;location.hash='search';renderResults()}});const schoolSwitch=document.querySelector('.school-switch');schoolSwitch?.addEventListener('click',()=>goSchoolPicker(location.hash||'#home'));showFirstVisit();}
async function openBusiness(id){if(!publishedListingsLoaded)await loadPublishedListings();const b=getBusiness(id);if(!b){toast("That business is no longer available for this school.");location.hash="home";return;}const related=selectedBusinesses().filter(x=>x.id!==id&&x.cat===b.cat);const other=selectedBusinesses().filter(x=>x.id!==id&&x.cat!==b.cat);const rel=[...related,...other].slice(0,6);const trusted=b.trustedStore===true;const ratingText=b.ratingCount?`⭐ ${b.ratingAvg.toFixed(1)} · ${b.ratingCount} client ratings`:`No store ratings yet`;const share=`${location.origin}${location.pathname}#store/${encodeURIComponent(b.ownerUid)}`;$("#businessViewContent").innerHTML=`<div class="detail-head"><button class="back-btn" id="businessBack">← Back</button><span class="eyebrow">Gig / product</span></div><div class="detail-hero"><div class="detail-img">${businessImage(b,true)}</div><div><span class="eyebrow">${esc(b.cat)}</span><h1>${esc(b.name)} ${trusted?`<span class="trusted-badge">✓ Trusted store</span>`:""}</h1><p>${esc(b.about)}</p><p class="meta">📍 ${esc(b.loc)} · 🚚 ${esc(b.delivery)}</p><div class="detail-actions"><a class="primary whatsapp" href="${waUrl(b)}" target="_blank" rel="noopener">Contact me on WhatsApp</a>${b.email?`<a class="email-btn" href="mailto:${esc(b.email)}">Email</a>`:""}<button data-fav="${esc(b.id)}">${state.favorites.includes(b.id)?"♥ Saved":"♡ Save"}</button><button type="button" class="secondary-btn" id="openStoreBtn" data-action="view-store">View store</button></div><div class="store-rating-summary"><strong>${ratingText}</strong>${trusted?`<span class="trusted-note">Trusted store</span>`:""}<button type="button" class="link-btn" id="rateStoreBtn" data-action="rate-store">Rate this store</button></div></div></div><div class="detail-section"><h2>Business information</h2><div class="info-grid"><div><strong>Category</strong><span>${esc(b.cat)}</span></div><div><strong>Starting price</strong><span>₦${Number(b.price).toLocaleString()}</span></div><div><strong>Location</strong><span>${esc(b.loc)}</span></div><div><strong>Delivery</strong><span>${esc(b.delivery)}</span></div>${b.priceRange?`<div><strong>Price range</strong><span>${esc(b.priceRange)}</span></div>`:""}${b.hours?`<div><strong>Opening hours</strong><span>${esc(b.hours)}</span></div>`:""}${b.website?`<div><strong>Website</strong><span><a href="${esc(b.website)}" target="_blank" rel="noopener">Visit website</a></span></div>`:""}</div></div>${productCarousel(b)}${b.description?`<div class="detail-section"><h2>About this business</h2><p>${esc(b.description)}</p></div>`:""}<div class="detail-section comments-section" id="commentsSection"><div class="section-head"><div><span class="eyebrow">Community</span><h2>COMMENTS - <span id="commentCount">0</span></h2></div><button type="button" class="link-btn" id="toggleComments" data-action="toggle-comments">Show comments</button></div><div id="commentPanel" class="comment-panel hidden"><div id="commentList" class="comment-list"><p class="muted">Loading comments…</p></div><div class="comment-form"><textarea id="commentText" maxlength="500" placeholder="Share your experience with this gig or product…"></textarea><button type="button" class="primary" id="sendComment" data-action="send-comment">Send comment</button></div></div><p class="visibility-note">Comments help students make informed choices. Store owners cannot delete client comments.</p></div><div class="detail-section"><h2>Related businesses</h2><div class="grid">${rel.map(card).join("")||"<p>No related businesses yet.</p>"}</div></div>`;$("#businessBack").onclick=()=>{location.hash='home'};renderedBusiness=id;wireBusinessActions();loadComments(b.id);setupCommentToggle();const focusComments=new URLSearchParams(location.search).get('focus')==='comments';const desiredHash=`#businessView/${encodeURIComponent(id)}`;if(location.hash!==desiredHash)location.hash=desiredHash;if(focusComments)setTimeout(()=>{const panel=$("#commentPanel"),toggle=$("#toggleComments"),section=$("#commentsSection");panel?.classList.remove('hidden');if(toggle)toggle.textContent='Hide comments';section?.scrollIntoView({behavior:'smooth',block:'start'});},120)}
function storeFor(ownerUid){return selectedBusinesses().find(x=>x.ownerUid===ownerUid)||null}
function storeCard(b){return `<article class="store-card" data-store="${esc(b.ownerUid)}"><div class="store-card-img">${businessImage(b,true)}</div><div class="store-card-body"><strong>${esc(b.name)}</strong>${b.trustedStore?`<span class="trusted-badge">✓ Trusted store</span>`:""}<span>⭐ ${b.ratingCount?b.ratingAvg.toFixed(1):"New"} · ${b.ratingCount||0} ratings</span></div></article>`}
function setupCommentToggle(){}
function getBusinessIdFromView(){const active=location.hash.match(/businessView/);return document.querySelector('#businessViewContent [data-fav]')?.dataset.fav||''}
async function loadComments(listingId){const list=$("#commentList"),count=$("#commentCount");if(!list||!listingId)return;try{const r=await fetch(`/api/storage/upload?action=comments&listingId=${encodeURIComponent(listingId)}`);const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Unable to load comments.');count.textContent=String(d.count||0);list.innerHTML=(d.comments||[]).length?(d.comments||[]).map(c=>`<article class="comment"><strong>${esc(c.displayName||'CampBiz client')}</strong><time>${esc(new Date(c.createdAt).toLocaleString())}</time><p>${esc(c.text)}</p></article>`).join(''):`<p class="muted">No comments yet. Be the first to share your experience.</p>`}catch(e){list.innerHTML='<p class="muted">Comments are temporarily unavailable.</p>'}}
async function sendComment(){const text=$("#commentText")?.value.trim();if(!text)return toast('Write a comment first.');if(!auth.currentUser)return toast('Sign in with Google to comment.');const btn=$("#sendComment");btn.disabled=true;btn.textContent='Sending…';try{const token=await auth.currentUser.getIdToken();const id=getBusinessIdFromView();const r=await fetch('/api/storage/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({action:'comment',listingId:id,text})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Could not send comment.');$("#commentText").value='';toast('Your comment is sent.');await loadComments(id)}catch(e){toast(e.message||'Could not send comment.')}finally{btn.disabled=false;btn.textContent='Send comment'}}
async function rateStore(ownerUid){if(!auth.currentUser)return toast('Sign in with Google to rate a store.');if(auth.currentUser.uid===ownerUid)return toast('Store owners cannot rate their own store.');const modal=$("#modal");if(!modal)return;modal.innerHTML=`<div class="rating-sheet"><button class="icon-btn rating-close" type="button" aria-label="Close">×</button><span class="eyebrow">Store rating</span><h2>How was your experience?</h2><p class="muted">One rating per client account. You can update your existing rating.</p><div class="rating-choice" role="radiogroup">${[1,2,3,4,5].map(n=>`<button type="button" data-store-rate="${n}" aria-label="${n} stars">${n}★</button>`).join('')}</div><small class="muted">Ratings boost store visibility.</small></div>`;modal.classList.add('show');modal.querySelector('.rating-close').onclick=()=>modal.classList.remove('show');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('show')};modal.querySelectorAll('[data-store-rate]').forEach(btn=>btn.onclick=async()=>{const value=Number(btn.dataset.storeRate);modal.classList.remove('show');try{const token=await auth.currentUser.getIdToken();const r=await fetch('/api/storage/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({action:'rateStore',ownerUid,rating:value})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Could not save your rating.');toast(d.message||'Thanks for rating this store.');renderedStore="";renderedBusiness="";publishedListingsLoaded=false;publishedListings=[];await loadPublishedListings();location.hash=`store/${encodeURIComponent(ownerUid)}`;route()}catch(e){toast(e.message||'Could not save your rating.')}})}
async function openStore(ownerUid){if(!publishedListingsLoaded)await loadPublishedListings();const listings=selectedBusinesses().filter(x=>x.ownerUid===ownerUid);const b=listings[0];if(!b){toast("Store not found for this school.");location.hash="home";return;}const trusted=b.trustedStore;const share=`${location.origin}${location.pathname}#store/${encodeURIComponent(ownerUid)}`;$("#storeViewContent").innerHTML=`<div class="detail-head"><button class="back-btn" id="storeBack">← Back</button><span class="eyebrow">Store profile</span></div><div class="store-profile-hero"><div class="store-avatar">${businessImage(b,true)}</div><div><h1>${esc(b.name)} ${trusted?`<span class="trusted-badge">✓ Trusted store</span>`:""}</h1><p>${esc(b.about)}</p><p class="meta">${esc(b.school)} · ${esc(b.cat)}</p><div class="store-rating-large">⭐ ${b.ratingCount?b.ratingAvg.toFixed(1):'New'} · ${b.ratingCount||0} client ratings</div><p class="rating-boost-note">⭐ Ratings boost visibility. Ask your clients to rate your store after a successful order or service.</p><div class="detail-actions"><button type="button" class="primary" id="rateStoreProfile" data-action="rate-store">Rate this store</button><button type="button" class="secondary-btn" id="copyStoreLink" data-action="copy-store-link">Copy promotional store link</button></div></div></div><div class="detail-section"><h2>All gigs & products</h2><div class="grid">${listings.map(card).join('')||'<p class="muted">No published gigs or products yet.</p>'}</div></div>`;$("#storeBack").onclick=()=>{location.hash='home'};renderedStore=ownerUid;wireBusinessActions();location.hash=`store/${encodeURIComponent(ownerUid)}`}

function renderTools(){const html=TOOLS.map(t=>`<div class="tool-card" data-tool="${t[2]}"><strong>${t[0]}</strong><span>${t[1]}</span></div>`).join("");$("#toolsGrid").innerHTML=html;$("#toolPreview").innerHTML=TOOLS.slice(0,4).map(t=>`<div class="tool-card" data-tool="${t[2]}"><strong>${t[0]}</strong><span>${t[1]}</span></div>`).join("");document.querySelectorAll("[data-tool]").forEach(x=>x.onclick=()=>openTool(x.dataset.tool))}
let toolTimer=0;
function openTool(type){const p=$("#toolPanel");clearInterval(toolTimer);if(location.hash!=="#tools")location.hash="tools";p.classList.remove("hidden");const map={gpa:`<h2>GPA Calculator</h2><p>Add courses, units and scores.</p><div id="courseRows"></div><button class="actions" id="addCourse">＋ Add course</button><button class="primary" id="calc">Calculate GPA</button><div id="out"></div>`,cgpa:`<h2>CGPA Calculator</h2><p>Add every course/result you want included.</p><div id="courseRows"></div><button class="actions" id="addCourse">＋ Add course</button><button class="primary" id="calc">Calculate CGPA</button><div id="out"></div>`,percent:`<h2>Percentage Calculator</h2><input id="a" type="number" placeholder="Value"><input id="b" type="number" placeholder="Percent"><button class="primary" id="calc">Calculate</button><div id="out"></div>`,grade:`<h2>Target Score Calculator</h2><input id="total" type="number" placeholder="Total marks"><input id="current" type="number" placeholder="Marks already secured"><input id="target" type="number" placeholder="Target percentage"><button class="primary" id="calc">Calculate</button><div id="out"></div>`,timer:`<h2>Study Timer</h2><input id="mins" type="number" value="25" min="1"><button class="primary" id="start">Start</button><div id="out" class="tool-result">25:00</div>`,words:`<h2>Word Counter</h2><textarea id="txt" rows="8" placeholder="Paste or type your text..."></textarea><div id="out" class="tool-result">0 words · 0 characters</div>`,units:`<h2>Unit Converter</h2><input id="unit" type="number" placeholder="Value"><select id="from"><option>km</option><option>m</option><option>kg</option><option>g</option><option>C</option><option>F</option></select><select id="to"><option>m</option><option>km</option><option>g</option><option>kg</option><option>C</option><option>F</option></select><button class="primary" id="calc">Convert</button><div id="out"></div>`,deadline:`<h2>Deadline Countdown</h2><input id="date" type="datetime-local"><button class="primary" id="start">Start countdown</button><div id="out" class="tool-result">Choose a deadline.</div>`,notes:`<h2>Private Notes</h2><textarea id="notes" rows="12" placeholder="Your notes stay on this device."></textarea><div class="muted">Saved locally.</div>`};p.innerHTML=map[type]||"<h2>Tool unavailable</h2>";setTimeout(()=>p.scrollIntoView?.({behavior:"smooth",block:"start"}),50);if(type==="gpa"||type==="cgpa"){const rows=$("#courseRows");const addRow=()=>{const row=document.createElement("div");row.className="course-row";row.innerHTML=`<input class="course-name" placeholder="Course"><input class="course-unit" type="number" min="0" step="0.5" placeholder="Units"><input class="course-score" type="number" min="0" max="100" placeholder="Score"><button type="button" class="remove-course">×</button>`;rows.appendChild(row);row.querySelector(".remove-course").onclick=()=>row.remove()};$("#addCourse").onclick=addRow;addRow();$("#calc").onclick=()=>{const scale=s=>s>=70?5:s>=60?4:s>=50?3:s>=45?2:s>=40?1:0;let units=0,points=0;rows.querySelectorAll(".course-row").forEach(r=>{const u=+r.querySelector(".course-unit").value,sc=+r.querySelector(".course-score").value;if(u>0&&sc>=0&&sc<=100){units+=u;points+=u*scale(sc)}});$("#out").innerHTML=units?`<div class="tool-result">${type.toUpperCase()}: ${(points/units).toFixed(2)}</div>`:`<div class="tool-result">Add valid course units and scores first.</div>`}}if(type==="percent")$("#calc").onclick=()=>$("#out").innerHTML=`<div class="tool-result">${((+$("#a").value||0)*(+$("#b").value||0)/100).toLocaleString()}</div>`;if(type==="grade")$("#calc").onclick=()=>{let need=((+$("#target").value||0)/100*(+$("#total").value||0))-(+$("#current").value||0);$("#out").innerHTML=`<div class="tool-result">Marks needed: ${Math.max(0,need).toFixed(2)}</div>`};if(type==="words")$("#txt").oninput=()=>{let s=$("#txt").value;$("#out").textContent=`${s.trim()?s.trim().split(/\s+/).length:0} words · ${s.length} characters`};if(type==="notes"){$("#notes").value=localStorage.getItem("cbc_notes")||"";$("#notes").oninput=()=>localStorage.setItem("cbc_notes",$("#notes").value)}if(type==="timer")$("#start").onclick=()=>{let sec=Math.round(Math.max(1,+$("#mins").value||25)*60);const out=$("#out");clearInterval(toolTimer);const id=toolTimer=setInterval(()=>{sec--;out.textContent=`${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`;if(sec<=0){clearInterval(id);toast("Study session complete!")}},1000)};if(type==="deadline")$("#start").onclick=()=>{const target=new Date($("#date").value).getTime();if(!target||target<=Date.now()){toast("Choose a future deadline.");return}const out=$("#out");clearInterval(toolTimer);const id=toolTimer=setInterval(()=>{const d=target-Date.now();if(d<=0){clearInterval(id);out.textContent="Deadline reached.";return}out.textContent=`${Math.floor(d/86400000)}d ${Math.floor(d%86400000/36e5)}h ${Math.floor(d%36e5/6e4)}m ${Math.floor(d%6e4/1000)}s remaining`},1000)};if(type==="units")$("#calc").onclick=()=>{const raw=$("#unit").value;const v=+raw;const f=$("#from").value,t=$("#to").value;if(raw===""||!Number.isFinite(v)){$("#out").innerHTML='<div class="tool-result">Enter a value first.</div>';return}const L={km:1000,m:1},M={kg:1000,g:1};let r;if(f in L&&t in L)r=v*L[f]/L[t];else if(f in M&&t in M)r=v*M[f]/M[t];else if(f==="C"&&t==="F")r=v*9/5+32;else if(f==="F"&&t==="C")r=(v-32)*5/9;else if(f===t)r=v;$("#out").innerHTML=r===undefined?'<div class="tool-result">Pick two units of the same type.</div>':`<div class="tool-result">${Number(r.toFixed(6)).toLocaleString(undefined,{maximumFractionDigits:6})}</div>`}}
function openAdComingSoon(){const m=$("#modal");const min=1000,max=100000,step=1000;m.innerHTML=`<div class="modal-card"><button class="modal-close" id="modalClose">×</button><span class="eyebrow">Sponsored advertising</span><h2>Coming soon</h2><p>Advertising will open after CampBiz has enough active users. The calculator below shows the planned pricing only.</p><div class="ad-preview"><label for="budgetRange">Budget</label><input id="budgetRange" class="vertical-range" type="range" min="${min}" max="${max}" step="${step}" value="10000"><div class="ad-numbers"><strong id="budgetValue">₦10,000</strong><span id="impressionValue">12,000 impressions</span></div><p class="muted">Planned rate: ₦1,000 per 1,200 impressions. Impressions are calculated from budget, not subscriber count.</p><button class="primary" disabled>Advertising unavailable</button></div></div>`;m.classList.add("show");$("#modalClose").onclick=()=>m.classList.remove("show");const r=$("#budgetRange");const update=()=>{$("#budgetValue").textContent=`₦${(+r.value).toLocaleString()}`;$("#impressionValue").textContent=`${(+r.value/1000*1200).toLocaleString()} impressions`};r.oninput=update;update()}
