function ownerTrialKey(user){return `campbiz_owner_trial_${user.uid}`}
async function fetchBillingStatus(user){
 if(!user)return null;
 try{const token=await user.getIdToken();const r=await fetch("/api/subscription/status",{headers:{Authorization:`Bearer ${token}`}});return await r.json()}catch(e){console.error("Billing status failed",e);return null}
}
let ownerAccessRun=0,trialActivationTried=false;
async function updateOwnerAccess(user){
  const run=++ownerAccessRun;
  const btn=$("#subscribeAnnual"),dash=$("#ownerDashboard"),status=$("#subscriptionStatus"),trial=$("#trialStatus");
  if(trial)trial.textContent="";
  if(!user){ownerListing={};ownerBillingStatus=null;trialActivationTried=false;btn.classList.add("hidden");dash.classList.add("hidden");status.textContent="Sign in with Google to create your business profile and start your free access.";return}
  loadOwnerDraft(user);dash.classList.remove("hidden");renderOwnerDashboard();
  if((user.email||"").toLowerCase()===OWNER_FREE_EMAIL){btn.classList.add("hidden");status.textContent="Lifetime free access is active.";return}
  btn.classList.remove("hidden");
  const billing=await fetchBillingStatus(user);
  if(run!==ownerAccessRun)return;
  if(!billing||billing.ok!==true){ownerBillingStatus=null;status.textContent="We could not load your billing status. Check your connection and try again.";btn.textContent="Retry loading billing";btn.onclick=()=>updateOwnerAccess(auth.currentUser);return}
  ownerBillingStatus=billing;
  renderOwnerDashboard();
  if(billing.active){status.textContent="Your Pro access is active.";btn.textContent="Billing active";btn.onclick=()=>toast("Your Paystack subscription is active.");return}
  if(billing.trialActive){const days=Math.max(1,Math.ceil((new Date(billing.trialEndsAt)-Date.now())/86400000));if(trial)trial.textContent=`All Pro features free · ${days} day${days===1?"":"s"} remaining${billing.trialBillingReady?" · billing set up":""}.`;status.textContent=billing.trialBillingReady?"Your free trial is active and billing is ready for after the trial.":"Your 2-month Pro trial is active.";btn.textContent=billing.trialBillingReady?"Billing already set up":"Set up billing after trial";btn.onclick=billing.trialBillingReady?()=>toast("Billing is already set up."):enrollTrialBilling;return}
  if(billing.trialBillingReady){btn.textContent="Start Pro billing";status.textContent="Your free trial has ended. Starting the selected recurring plan…";btn.onclick=activateTrialBilling;if(!trialActivationTried){trialActivationTried=true;activateTrialBilling()}return}
  if(trial)trial.textContent="Your 2-month free Pro trial has ended. Store locked.";status.textContent="Your store is locked. Upgrade to make your gigs visible to students again.";btn.textContent="Upgrade to unlock store";btn.onclick=openUpgradeModal;
}

