function openUpgradeModal(){const m=$("#modal");if(!m)return;const locked=ownerLocked();m.innerHTML=`<div class="modal-card upgrade-card"><button class="modal-close" id="upgradeClose" type="button" aria-label="Close">×</button><span class="eyebrow">CampBiz Pro</span><h2>${locked?"Unlock your store":"Upgrade to Pro"}</h2><p class="muted">${locked?"Your free trial has ended, so your store and gigs are hidden from students. Your ratings, rank and listing details are saved and come back the moment payment is confirmed.":"Keep your store and gigs live for students at your school."}</p><div class="upgrade-plans"><label class="upgrade-plan"><input type="radio" name="upgradePlan" value="monthly" checked><span><strong>Monthly</strong><small>${esc(priceLabel("monthly"))}</small></span></label><label class="upgrade-plan"><input type="radio" name="upgradePlan" value="annual"><span><strong>Annual</strong><small>${esc(priceLabel("annual"))}</small></span></label></div><ul class="upgrade-features"><li>✓ Store and all gigs visible on the student feed</li><li>✓ Public store page and shareable store link</li><li>✓ Gallery of up to ${PRO_PRODUCT_IMAGE_LIMIT} product images (free: ${FREE_PRODUCT_IMAGE_LIMIT})</li><li>✓ Ratings, rank and Trusted store badge keep counting</li><li>✓ Comment notifications</li></ul><button class="primary" id="upgradePayBtn" type="button">Continue to Paystack</button><small class="muted">Pro unlocks only after Paystack confirms your payment.</small></div>`;m.classList.add("show");$("#upgradeClose").onclick=()=>m.classList.remove("show");m.onclick=e=>{if(e.target===m)m.classList.remove("show")};$("#upgradePayBtn").onclick=async()=>{const plan=m.querySelector('input[name="upgradePlan"]:checked')?.value||"monthly";const b=$("#upgradePayBtn");b.disabled=true;b.textContent="Opening Paystack…";try{await startSubscription(plan)}finally{b.disabled=false;b.textContent="Continue to Paystack"}}}
async function finishDriveConnection(result){const user=auth.currentUser||result?.user;if(!user)throw new Error("Google sign-in session was not restored.");const credential=GProvider.credentialFromResult(result);const token=credential?.accessToken;if(!token)throw new Error("Google Drive authorization was not returned.");const idToken=await user.getIdToken();const verified=await fetch("/api/storage/upload",{method:"POST",headers:{Authorization:`Bearer ${idToken}`,"Content-Type":"application/json"},body:JSON.stringify({action:"connect",accessToken:token})});const vd=await verified.json().catch(()=>({}));if(!verified.ok||!vd.ok)throw new Error(vd.error||"CampBiz could not verify Google Drive.");saveDriveConnection(user,true);toast("Google Drive connected successfully.");renderOwnerDashboard()}
async function connectOwnerDrive(){const user=auth.currentUser;if(!user){toast("Sign in with Google first.");return}const btn=$("#connectDriveBtn");btn.disabled=true;btn.textContent="Connecting Google Drive…";try{const provider=new GProvider();provider.addScope("https://www.googleapis.com/auth/drive.file");if(/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)){sessionStorage.setItem("campbiz_drive_reauth","1");await reauthenticateWithRedirect(user,provider);return}await finishDriveConnection(await reauthenticateWithPopup(user,provider))}catch(e){console.error("Drive connection failed",e);toast(e.message||"Google Drive connection failed.")}finally{if(btn){btn.disabled=false;btn.textContent="Connect Google Drive"}}}

async function enableOwnerCommentNotifications(){const user=auth.currentUser;if(!user)return toast("Sign in with Google first.");const btn=$("#enableOwnerNotifications");if(btn){btn.disabled=true;btn.textContent="Enabling notifications…"}try{const {enableCampusNotifications}=await import("./fcm-client.js");const token=await user.getIdToken();await enableCampusNotifications({authToken:token,schoolId:ownerListing.school||state.school||"",anonymousId:user.uid});localStorage.setItem(`campbiz_fcm_enabled_${user.uid}`,"1");toast("Comment notifications are enabled.");if(btn)btn.textContent="✓ Comment notifications enabled"}catch(e){console.error("FCM registration failed",e);toast(e.message||"Could not enable notifications.");if(btn){btn.disabled=false;btn.textContent="Enable comment notifications"}}}

